static inline int max2(int a, int b) { return a > b ? a : b; }

int main(void) {
    char S[5005];
    int K;
    if (scanf("%s %d", S, &K) != 2) return 0;

    int N = (int)strlen(S);

    /*
      The value of T is LCS(T, reverse(T)), which equals the length
      of the longest palindromic subsequence of T.

      After changing at most K characters, we want to maximize LPS.

      Consider symmetric pairs (i, N-1-i).
      If S[i] == S[j], they can contribute 2 to a palindrome without cost.
      If S[i] != S[j], by changing one of them we can make them equal,
      so such a pair can also contribute 2 with cost 1.

      Therefore, starting from the original string:
      - every already-equal symmetric pair contributes 2
      - every mismatched symmetric pair can be fixed with cost 1 to gain +2
      - if N is odd, the center always contributes 1

      Let mism = number of mismatched symmetric pairs.
      With at most K changes, we can fix min(K, mism) such pairs.

      Hence answer:
        base = 2 * (#equal pairs) + (N % 2)
             = N - mism * 2? easier to derive directly:
        maximum LPS = N - max(0, mism - K) * 2

      More directly:
        if K >= mism => answer = N
        else answer = N - 2 * (mism - K)
    */

    int mism = 0;
    for (int i = 0; i < N / 2; i++) {
        if (S[i] != S[N - 1 - i]) mism++;
    }

    int rem = mism - K;
    if (rem < 0) rem = 0;

    int ans = N - 2 * rem;
    printf("%d\n", ans);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main() {
    char S[2005];
    int K;
    scanf("%s %d", S, &K);
    int n = strlen(S);
    int mismatches = 0;
    for (int i = 0; i < n/2; i++) {
        if (S[i] != S[n-1-i]) mismatches++;
    }
    int fixed = K < mismatches ? K : mismatches;
    int remaining = mismatches - fixed;
    int lps = n - remaining - (remaining > 0 ? 0 : 0);
    // matched pairs: (n/2 - mismatches), each contributes 2
    // fixed pairs: fixed, each contributes 2
    // remaining pairs: remaining, each contributes 1 (best we can do)
    // middle: n%2
    lps = 2*(n/2 - mismatches) + 2*fixed + remaining + n%2;
    printf("%d\n", lps);
    return 0;
}

