int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    int K;
    cin >> S >> K;
    int n = S.size();

    // dp[l][r][k]
    vector<vector<vector<int>>> dp(n, vector<vector<int>>(n, vector<int>(K+1, 0)));

    // Base case: single character
    for (int i = 0; i < n; i++) {
        for (int k = 0; k <= K; k++) {
            dp[i][i][k] = 1;
        }
    }

    // Base case: two characters
    for (int i = 0; i < n-1; i++) {
        for (int k = 0; k <= K; k++) {
            if (S[i] == S[i+1]) {
                dp[i][i+1][k] = 2;
            } else {
                dp[i][i+1][k] = 1;
                if (k >= 1) {
                    dp[i][i+1][k] = 2;
                }
            }
        }
    }

    // Fill DP for longer lengths
    for (int len = 3; len <= n; len++) {
        for (int l = 0, r = len-1; r < n; l++, r++) {
            for (int k = 0; k <= K; k++) {
                if (S[l] == S[r]) {
                    dp[l][r][k] = 2 + dp[l+1][r-1][k];
                } else {
                    dp[l][r][k] = max(dp[l+1][r][k], dp[l][r-1][k]);
                    if (k >= 1) {
                        dp[l][r][k] = max(dp[l][r][k], 2 + dp[l+1][r-1][k-1]);
                    }
                }
            }
        }
    }

    cout << dp[0][n-1][K] << "\n";
    return 0;
}

