#include <bits/stdc++.h>
using namespace std;

/*
Value(T) = LCS(T, reverse(T)) = length of the Longest Palindromic Subsequence of T.

We may change at most K characters of S to maximize this value.

Key fact:
For any substring S[l..r], let need(l,r) be the minimum number of character changes
required to make the whole substring a palindrome.
This is exactly the number of mismatched mirrored pairs inside the substring.

Then a palindromic subsequence of length len exists after at most K changes
iff there exists a substring of length len with need <= K:
- If such substring exists, we can change it into a palindrome, so its whole length
  becomes a palindromic subsequence.
- Conversely, take any chosen subsequence positions i1 < ... < it. To make that
  subsequence a palindrome, for each mirrored pair among these chosen positions,
  if characters differ, at least one change is needed. The number of such needed
  changes is at least the number of mismatched mirrored pairs in the enclosing
  interval [i1, it] when considering those chosen pairs. But for any interval,
  the minimum changes to make the entire interval a palindrome is exactly the count
  of mismatched mirrored pairs, and any subsequence of that interval of the same
  length can do no better than taking the whole interval. Thus it is enough to
  search over substrings.

So we compute for every substring the number of mismatched mirrored pairs:
dp[l][r] = dp[l+1][r-1] + (S[l] != S[r]) for l < r.

Then answer is the maximum length (r-l+1) with dp[l][r] <= K.

Complexity: O(N^2) time, O(N^2) memory.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string S;
    int K;
    cin >> S >> K;
    int N = (int)S.size();

    vector<vector<int>> dp(N, vector<int>(N, 0));

    int ans = 0;
    for (int len = 1; len <= N; ++len) {
        for (int l = 0; l + len - 1 < N; ++l) {
            int r = l + len - 1;
            if (l == r) {
                dp[l][r] = 0;
            } else if (r == l + 1) {
                dp[l][r] = (S[l] != S[r]);
            } else {
                dp[l][r] = dp[l + 1][r - 1] + (S[l] != S[r]);
            }
            if (dp[l][r] <= K) ans = max(ans, len);
        }
    }

    cout << ans << '\n';
    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String S = sc.next();
        int K = sc.nextInt();
        int n = S.length();

        int[][][] dp = new int[n][n][K+1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k <= K; k++) {
                    dp[i][j][k] = -1;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= K; k++) {
                dp[i][i][k] = 1;
            }
        }
        for (int i = 0; i < n-1; i++) {
            for (int k = 0; k <= K; k++) {
                if (S.charAt(i) == S.charAt(i+1)) {
                    dp[i][i+1][k] = 2;
                } else if (k > 0) {
                    dp[i][i+1][k] = 2;
                } else {
                    dp[i][i+1][k] = 1;
                }
            }
        }

        for (int len = 2; len < n; len++) {
            for (int l = 0; l + len < n; l++) {
                int r = l + len;
                for (int k = 0; k <= K; k++) {
                    int best = 0;
                    // skip left
                    if (dp[l+1][r][k] > best) best = dp[l+1][r][k];
                    // skip right
                    if (dp[l][r-1][k] > best) best = dp[l][r-1][k];
                    // match
                    if (S.charAt(l) == S.charAt(r)) {
                        if (dp[l+1][r-1][k] + 1 > best) best = dp[l+1][r-1][k] + 1;
                    } else if (k > 0) {
                        if (dp[l+1][r-1][k-1] + 1 > best) best = dp[l+1][r-1][k-1] + 1;
                    }
                    dp[l][r][k] = best;
                }
            }
        }

        System.out.println(dp[0][n-1][K]);
    }
}

