import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String S = fs.next();
        int K = fs.nextInt();

        int n = S.length();
        int mismatchedPairs = 0;

        for (int i = 0; i < n / 2; i++) {
            if (S.charAt(i) != S.charAt(n - 1 - i)) mismatchedPairs++;
        }

        int answer = n;
        if (mismatchedPairs > K) {
            answer = n - (mismatchedPairs - K) * 2;
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

def solve():
    import sys
    input = sys.stdin.readline

    S = input().strip()
    K = int(input().strip())
    n = len(S)

    # dp[l][r] = max LPS length with exactly 0 changes (baseline)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for l in range(0, n - length + 1):
            r = l + length - 1
            if S[l] == S[r]:
                dp[l][r] = dp[l+1][r-1] + 2
            else:
                dp[l][r] = max(dp[l+1][r], dp[l][r-1])

    # Now we allow up to K changes
    # dp2[l][r][k] can be large, so we do iterative over k
    # Use a 2D array for current k
    dp_k = [[0] * n for _ in range(n)]

    # Initialize for k=0
    for i in range(n):
        dp_k[i][i] = 1
    for length in range(2, n + 1):
        for l in range(0, n - length + 1):
            r = l + length - 1
            if S[l] == S[r]:
                dp_k[l][r] = dp_k[l+1][r-1] + 2
            else:
                dp_k[l][r] = max(dp_k[l+1][r], dp_k[l][r-1])

    for k in range(1, K + 1):
        new_dp = [[0] * n for _ in range(n)]
        for i in range(n):
            new_dp[i][i] = 1
        for length in range(2, n + 1):
            for l in range(0, n - length + 1):
                r = l + length - 1
                # match or change
                if S[l] == S[r]:
                    new_dp[l][r] = new_dp[l+1][r-1] + 2
                else:
                    # option to change one of them
                    change_cost = new_dp[l+1][r-1] + 2
                    skip_l = new_dp[l+1][r]
                    skip_r = new_dp[l][r-1]
                    new_dp[l][r] = max(skip_l, skip_r, change_cost)
        dp_k = new_dp

    print(dp_k[0][n-1])

